			--hover-bg: #f9f9f9;
			--badge-bg: #e3f2fd;
			--badge-text: #1976d2;
			--badge-spectrum-bg: #e8f5e9;
			--badge-spectrum-text: #388e3c;
		}
		@media (prefers-color-scheme: dark) {
			:root {
				--bg-primary: #1a1a1a;
				--bg-card: #2b2b2b;
				--text-primary: #eee;
				--text-secondary: #aaa;
				--text-muted: #777;
				--border-color: #444;
				--link-color: #90caf9;
				--shadow: 0 1px 3px rgba(255,255,255,0.1);
				--th-bg: #616161;
				--hover-bg: #333;
				--badge-bg: rgba(144, 202, 249, 0.2);
